 const workspaceSlug:Record<string,string>={'Overview':'overview','Vendor register':'register','Business hubs':'hubs','Trading locations':'locations','Fees & payments':'fees','Compliance':'compliance','Users':'users','Follow-ups':'follow-ups','Unit inventory':'inventory','Permits & cards':'permits','Tariffs & reports':'tariffs','Notice queue':'notices','Audit':'audit','Settings':'settings','Import':'import','Sessions':'sessions'};
