 function setPage(next:string){setPageState(next);setSelected(null);if(urlLock.current)return;const slug=workspaceSlug[next];const params=new URLSearchParams();if(slug&&slug!=='overview')params.set('workspace',slug);const search=params.toString();if(location.pathname==='/'&&(location.search||'')!==(search?'?'+search:''))history.pushState(null,'',search?'/?'+search:'/');}
 function workspaceBlurb(name:string){const blurbs:Record<string,string>={'Overview':'Registrations, trading spaces and compliance, all in one place.','Vendor register':'Manage formal and informal traders across the municipality.','Business hubs':'Add, rename and track allocations across the business hubs.','Users':'Add office staff and field officers, and decide who can sign in.','Trading locations':'Recorded GPS positions for informal street traders.','Fees & payments':'Keep a clear record of charges, payments and outstanding balances.','Compliance':'Review permit status, warnings and recorded violations.','Follow-ups':'Open cases, overdue follow-ups and who owns the next visit.','Unit inventory':'Available, occupied, reserved and unavailable units, plus allocation history.','Permits & cards':'Renewals, card issue, replacement and revocation.','Tariffs & reports':'Approved fees, receipts, reversals and reconciliation.','Notice queue':'Pending, failed and accepted notice deliveries.','Audit':'Searchable changes to vendors, hubs, payments and imports.','Settings':'Sender status, document requirements and how a locked-out account is recovered.','Import':'Check legacy rows, duplicates and invalid locations before they join the register.','Sessions':'Devices signed in to this account.'};return blurbs[name]||'';}
 const hubNames=hubRecords.map(item=>item.name);
 async function load(){setError('');try{const r=await fetch('/api/register');const j:any=await r.json();if(r.status===401){setAccount(null);return;}if(!r.ok)throw Error(j.error);if(Array.isArray(j.hubs)&&j.hubs.length)setHubRecords(j.hubs);setDeliveries(Array.isArray(j.deliveries)?j.deliveries:[]);setSenderConnected(Boolean(j.senderConnected));setOperations({units:j.units||[],pitches:j.pitches||[],tariffs:j.tariffs||[],permits:j.permits||[],requirements:j.requirements||[],allocationHistory:j.allocationHistory||[],imports:j.imports||[],audit:j.audit||[],settings:j.settings||{}});if(!j.vendors.length){setVendors(samples);vendorsRef.current=samples;setEntries(sampleEvents);setPreview(true);}else{setVendors(j.vendors);vendorsRef.current=j.vendors;setEntries(j.events);setPreview(false);const params=new URLSearchParams(location.search);setSelected(s=>{const id=s?.id||params.get('vendor');return id?j.vendors.find((v:Vendor)=>v.id===id)||null:null;});if(params.get('tab'))setTab(params.get('tab')||'Profile');}}catch(e){setError(e instanceof Error?e.message:'Unable to load');}finally{setLoading(false);}}
