 async function recordNotice(eventId:string,action:string,extra?:string){if(noticeBusy)return;setNoticeBusy(eventId+action);try{const r=await fetch('/api/notice',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,eventId,method:action==='deliver'?extra:'',note:action==='escalate'?extra:'',idempotencyKey:crypto.randomUUID().replace(/-/g,'').slice(0,24)})});const j:any=await r.json();if(!r.ok)throw Error(j.error);setToast(j.message||'Notice record saved.');await load();}catch(e){setToast(e instanceof Error?e.message:'Could not record this notice.');}finally{setNoticeBusy('');}}
 useEffect(()=>{(async()=>{try{const r=await fetch('/api/auth');const j:any=await r.json();setSetupRequired(!!j.setupRequired);if(r.ok&&j.user){setAccount(j.user);if(j.user.mustChangePassword||j.user.role==='field')setLoading(false);else await load();}else setLoading(false);}catch{setLoading(false);}finally{setAuthReady(true);}})();},[]);useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t);}},[toast]);useEffect(()=>{const apply=()=>{const params=new URLSearchParams(location.search);const slug=params.get('workspace')||'overview';const next=Object.entries(workspaceSlug).find(([,value])=>value===slug)?.[0]||'Overview';urlLock.current=true;setPageState(next);if(params.get('tab'))setTab(params.get('tab')||'Profile');setSelected(params.has('vendor')?vendorsRef.current.find(item=>item.id===params.get('vendor'))||null:null);urlLock.current=false;};apply();window.addEventListener('popstate',apply);return()=>window.removeEventListener('popstate',apply);},[]);useEffect(()=>{const f=(e:KeyboardEvent)=>{if(e.key!=='Escape')return;if(editing){closeEditing();return;}if(event){closeEvent();return;}if(hubForm){setHubForm(null);return;}if(card){setCard(null);return;}closeProfile();};window.addEventListener('keydown',f);return()=>window.removeEventListener('keydown',f);},[editing,event,hubForm,card,selected]);useEffect(()=>{const root=(document.querySelector('.overlay.front')||document.querySelector('[role="dialog"]')) as HTMLElement|null;if(!root)return;const previous=document.activeElement as HTMLElement|null;const items=()=>[...root.querySelectorAll<HTMLElement>('button,a,input,select,textarea')].filter(el=>!el.hasAttribute('disabled'));items()[0]?.focus();const onKey=(e:KeyboardEvent)=>{if(e.key!=='Tab')return;const list=items();if(!list.length)return;const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}};root.addEventListener('keydown',onKey);return()=>{root.removeEventListener('keydown',onKey);previous?.focus();};},[selected,editing,event,card,hubForm]);
 async function save(body:any){setBusy(true);try{const r=await fetch('/api/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j:any=await r.json();if(!r.ok)throw Error(j.error);await load();setToast('Saved to the vendor register');return true;}catch(e){setToast(e instanceof Error?e.message:'Could not save. Please try again.');return false;}finally{setBusy(false);}}
 function liveAction(v:Vendor,action:()=>void){if(preview){setToast('Load sample records first to try saved workflows, or register a new vendor to start your live register.');return;}action();}
 if(!authReady)return <div className="login-screen"><p>Checking your session…</p></div>;
 if(!account)return <LoginScreen setupRequired={setupRequired} onSuccess={async user=>{setAccount(user);setSetupRequired(false);if(user.mustChangePassword||user.role==='field')return;setLoading(true);await load();}}/>;
