 const filtered=vendors.filter(v=>(!query||[v.id,v.name,v.business,v.unit,v.sector,v.hub].join(' ').toLowerCase().includes(query.toLowerCase()))&&(type==='All types'||v.type===type)&&(hub==='All locations'||(hub==='Street trading'?v.type==='Informal':v.hub===hub))&&(status==='All statuses'||permit(v)===status));
 const cases=entries.filter(openCase),totalDue=vendors.reduce((n,v)=>n+Math.max(0,balance(v.id,entries)),0),paid=netTotal(entries,'Payment'),charged=netTotal(entries,'Charge'),formal=vendors.filter(v=>v.type==='Formal').length;
